List<String> art(String text) {
  const symbols = ['.', '*', '#', '@'];
  final width = max((text.length * 4), 20).round();
  final height = text.length * 3 + 2;
  List<String> result = [];
  int y = 1;

  result.add('~' * width);

  for (var i = 0; i < text.length; i++) {
    char ch = text.codeUnitAt(i);
    if (ch == ' ') {

      result.add(' '.padRight(width));
    } else {


      var index = (int.tryParse(ch.toString()) ?? 0) % symbols.length;
      String symbol = symbols[index];
      var block = '''${symbol}${symbol}${symbol}|
|${symbol.padLeft(3, ' ')}|
| ${symbol.padLeft(2, ' ')}'''.split('\n').map((line) => line.padRight(width)).toList();
      for (var j = 0; j < block.length; j++) {
        result[y++] += block[j] + '~';
      }
    }
  }

  result.add('~' * width);
  return result.take(height - 1).toList();
}

