  final List<List<int>> adj;

  int v, e;

  Digraph(this.v) : adj = List.generate(v, (_) => []), e = 0 {
    for (int i = 0; i < v; ++i) {
      for (int j = i + 1; j < v; ++j) {
        if (adj[i].contains(j)) continue;
        adj[i].add(j);
        adj[j].add(i);
        e++;
      }
    }
  }

  void addEdge(int a, int b) {
    if (a >= 0 && a < v && b >= 0 && b < v && !adj[a].contains(b) &&
        !adj[b].contains(a)) {
      adj[a].add(b);
      adj[b].add(a);
      e++;
    } else throw ArgumentError('edge $a-$b already exists or out of range');
  }

