    var t = verticesSet[i1];
    verticesSet.removeAt(i1);
    verticesSet.insertAll(i1, [verticesSet[i2]]);
    verticesSet.removeAt(i1 + 1);
    verticesSet.insertAll(i2, [t]);
    _updateEdgeReferences(verticesSet[i1], verticesSet[i2]);
