  if (n <= 2 || hull == null) return [];
  if (hull.isEmpty && n > 0) {
    hull.add(0);
    hull.add(1);
  } else if (hull.length >= 4) {

    for (int i = 0; i < n - 1; i++) {
      double x = points[i];
      double y = points[i + 1];

      double d = cross(points[hull[0]], points[hull[1]], points[hull[2]]);

      if ((d * (x - points[hull[0]][0]) + 
           d * (y - points[hull[0]][1])) > 0) {
