      }
      hull.removeRange(0, 2);
    }

    int m = hull.last + 1;
    while (m >= 0) {
      addPointToHull(m % n);
      m -= n;
    }
  } else if (hull.isNotEmpty) {

    int a = hull.first;
    int b = (a + 1) % n;
    int c = (b + 1) % n;

    addPointsBetween(a, b, true);
    addPointsBetween(b, c, false);
    addPointsBetween(c, a, false);
  }

  print('Updated Hull: $hull');
}

double quickHull3D(List<Point> points) {
  if (points.isEmpty || points.length < 4) return [];


  var hull = getInitialHull(points);
  List<List<Point>> left, right;


  for (var p in points) {
    bool isOnLeftHalfSpace(Point a, Point b, Point c, Point q) =>
        Vector.cross(a - c, b - c).dot(q - c) > 0.0;

    double dist(Point a, Point b, Point c) =>
        Vector.cross(a - c, b - c).magnitude;


    bool onLeftOfPlane(Point a, Point b, Point c, Point q) =>
        isOnLeftHalfSpace(a, b, c, q);


    bool closerToEdge(Point p1, Point p2, Point q) =>
        dist(p1, p2, Vector.midpoint(p1, p2)) > dist(q, p1, p2);



    List<bool> leftFlags = [true] * points.length;
    for (int i = 0; i < hull.length; ++i) {
      int j = (i + 1) % hull.length;
      for (int k = 0; k < points.length; ++k) {

        if (!onLeftOfPlane(hull[i], hull[j], Vector.midpoint(hull[i], hull[j]), points[k])) continue;
        if (closerToEdge(hull[i], hull[j], points[k]) && !leftFlags[k]) {
          leftFlags[k] = true;

        } else if (!closerToEdge(hull[i], hull[j], points[k])) {
          break; 
        }
      }
    }

    left = [], right = [];
    for (int k = 0; k < points.length; ++k) {
      if (leftFlags[k]) left.add(points[k]);
      else              right.add(points[k]);
    }


    var newPoints = quickHull3D(left);
    var oldPoints = quickHull3D(right);
    hull.addAll(newPoints);
    hull.addAll(oldPoints);
  }

  return hull.takeWhile((p) => p != null).toList(); 
}

