      int pt1 = 0, pt2 = 0;
      for (int i = 0; i < 3; ++i) {
        if (points[cur].equals(_Globals.facets[f].plane.vectorAtIndex(i))) pt1 = i;
        if (points[net].equals(_Globals.facets[f].plane.vectorAtIndex(i))) pt2 = i;
