    // 4️⃣ Re‑assign points that were stored in the deleted facets
    // -------------------------------------------------
    _Globals.resPt.clear();
    for (final int fId in _Globals.resFDel) {
      _Globals.resPt.addAll(_Globals.hullPoints[fId]);
      _Globals.hullPoints[fId].clear();
    }

